--
-- Name: check_feature_pipeline_freshness(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_feature_pipeline_freshness() RETURNS TABLE(symbol text, tf text, last_ts timestamp with time zone, gap_minutes double precision)
    LANGUAGE sql
    AS $$
    SELECT symbol, tf, MAX(ts) as last_ts,
           EXTRACT(EPOCH FROM (NOW() - MAX(ts))) / 60.0 as gap_minutes
    FROM intelligence_features
    WHERE ts > NOW() - INTERVAL '30 minutes'
    GROUP BY symbol, tf
    HAVING MAX(ts) < NOW() - INTERVAL '10 minutes'
    ORDER BY gap_minutes DESC;
$$;


