    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'research_run is append-only: % is not allowed', TG_OP
        USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION public.fn_research_run_no_delete() OWNER TO postgres;

--
-- Name: FUNCTION fn_research_run_no_delete(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_research_run_no_delete() IS 'Refuses DELETE (row trigger) and TRUNCATE (statement trigger) on research_run (migration 366): run records are permanent, a run that was seen cannot be unseen.';


--
-- Name: fn_research_run_series_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_research_run_series_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_status text;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'research_run_series is append-only: % is not allowed', TG_OP
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT status INTO parent_status FROM research_run WHERE run_id = NEW.run_id;
    IF parent_status IS NULL OR parent_status NOT IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'research_run_series: run % must be terminal as completed or failed, is %',
            NEW.run_id, parent_status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_research_run_series_guard() OWNER TO postgres;

--
-- Name: instrument_classification_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.instrument_classification_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    today date;
BEGIN
    IF TG_OP = 'INSERT' THEN
        today := classification_write_date();
        IF NEW.valid_from <> today THEN
            RAISE EXCEPTION 'instrument_classification: insert for % must have valid_from = today % (got %); no backdated or scheduled rows (D-07)',
                NEW.symbol, today, NEW.valid_from;
        END IF;
        IF NEW.valid_to IS NOT NULL THEN
            RAISE EXCEPTION 'instrument_classification: insert for % must be open (valid_to NULL)', NEW.symbol;
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        today := classification_write_date();
        IF OLD.valid_to IS NOT NULL THEN
            RAISE EXCEPTION 'instrument_classification: row (%, %, %) is closed and immutable',
                OLD.symbol, OLD.scheme, OLD.valid_from;
        END IF;
        IF (NEW.symbol, NEW.scheme, NEW.code, NEW.valid_from, NEW.source_ref, NEW.created_at)
           IS DISTINCT FROM
           (OLD.symbol, OLD.scheme, OLD.code, OLD.valid_from, OLD.source_ref, OLD.created_at) THEN
            RAISE EXCEPTION 'instrument_classification: only valid_to may change (close the row, insert a new one)';
        END IF;
        IF NEW.valid_to IS DISTINCT FROM today THEN
            RAISE EXCEPTION 'instrument_classification: close % with valid_to = today % (got %)',
                OLD.symbol, today, NEW.valid_to;
        END IF;
        RETURN NEW;
    ELSE
        RAISE EXCEPTION 'instrument_classification is append-only: % is not allowed', TG_OP;
    END IF;
END $$;


ALTER FUNCTION public.instrument_classification_append_only() OWNER TO postgres;

--
-- Name: instruments_clear_eligibility_when_inactive(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.instruments_clear_eligibility_when_inactive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_active IS NOT TRUE THEN
    NEW.compute_eligible := false;
    NEW.compute_eligible_1d := false;
    NEW.live_tradeable := false;
  END IF;
  RETURN NEW;
END
$$;


