--
-- Name: listing_venue_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.listing_venue_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.valid_to IS NOT NULL THEN
            RAISE EXCEPTION 'listing_venue: span (%, %) is closed and immutable',
                OLD.symbol, OLD.valid_from USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.valid_to IS NULL THEN
            RAISE EXCEPTION 'listing_venue: an update must close the open span of % with a date',
                OLD.symbol USING ERRCODE = 'check_violation';
        END IF;
        IF (NEW.symbol, NEW.venue, NEW.valid_from, NEW.evidence, NEW.batch_id, NEW.recorded_at)
           IS DISTINCT FROM
           (OLD.symbol, OLD.venue, OLD.valid_from, OLD.evidence, OLD.batch_id, OLD.recorded_at) THEN
            RAISE EXCEPTION 'listing_venue: only valid_to may change (close the span, insert a new one)'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    ELSE
        RAISE EXCEPTION 'listing_venue is append-only: % is not allowed', TG_OP
            USING ERRCODE = 'check_violation';
    END IF;
END $$;


ALTER FUNCTION public.listing_venue_append_only() OWNER TO postgres;

--
-- Name: FUNCTION listing_venue_append_only(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.listing_venue_append_only() IS 'Allows INSERT and the one UPDATE that closes an open span (valid_to NULL to a date); refuses every other UPDATE, DELETE and TRUNCATE on listing_venue (migration 408).';


