--
-- Name: ohlcv_raw; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_raw (
    "timestamp" timestamp with time zone NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    vendor text NOT NULL,
    kind text NOT NULL,
    open double precision NOT NULL,
    high double precision NOT NULL,
    low double precision NOT NULL,
    close double precision NOT NULL,
    volume bigint,
    served_at timestamp with time zone,
    request_id uuid,
    load_id uuid,
    CONSTRAINT ohlcv_raw_finite CHECK (((open <> 'NaN'::double precision) AND (open <> 'Infinity'::double precision) AND (open <> '-Infinity'::double precision) AND (high <> 'NaN'::double precision) AND (high <> 'Infinity'::double precision) AND (high <> '-Infinity'::double precision) AND (low <> 'NaN'::double precision) AND (low <> 'Infinity'::double precision) AND (low <> '-Infinity'::double precision) AND (close <> 'NaN'::double precision) AND (close <> 'Infinity'::double precision) AND (close <> '-Infinity'::double precision)))
);


ALTER TABLE public.ohlcv_raw OWNER TO postgres;

--
-- Name: TABLE ohlcv_raw; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ohlcv_raw IS 'The one table of vendor answers (migration 472, phase 191): every bar a vendor served, at the timeframe it served, keyed by (vendor, kind), last-wins. Canonical market_data_ohlcv is a selection from here by bar_source_policy. A vendor changing its own answer is logged in ohlcv_revision; two vendors differing on a slot is a disagreement resolved by selection. No CHECK on vendor or kind: the writer validates against CVR bar_vendor and bar_kind.';


--
-- Name: COLUMN ohlcv_raw.served_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_raw.served_at IS 'When this value was first served; nullable only for rows migrated from stores that never captured it. No dummy ids and no now() stamps are allowed.';


--
-- Name: COLUMN ohlcv_raw.request_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_raw.request_id IS 'The ohlcv_request that first served this value; nullable only for migrated rows and loader-written rows. No dummy ids allowed.';


--
-- Name: COLUMN ohlcv_raw.load_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_raw.load_id IS 'The ohlcv_load write that set the row; nullable only for migrated rows that never had one. No dummy ids allowed.';


