--
-- Name: concept_transition_log; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.concept_transition_log (
    id bigint NOT NULL,
    concept_id uuid NOT NULL,
    domain text NOT NULL,
    name text NOT NULL,
    from_status text NOT NULL,
    to_status text NOT NULL,
    trigger_reason text NOT NULL,
    corpus_build_ref text,
    gate_metric double precision,
    gate_n double precision,
    ci_lower double precision,
    decay_ratio double precision,
    regime_scope text,
    triggered_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    CONSTRAINT concept_transition_log_trigger_reason_check CHECK ((trigger_reason = ANY (ARRAY['promotion'::text, 'demotion_performance'::text, 'demotion_decay'::text, 'demotion_redundancy'::text, 'operator_override'::text, 'parent_cascade'::text, 'candidate_timeout'::text, 'implementation_change'::text, 'genesis_seed'::text, 'data_quality_fail'::text, 'data_quality_restored'::text])))
);


ALTER TABLE public.concept_transition_log OWNER TO postgres;

--
-- Name: TABLE concept_transition_log; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.concept_transition_log IS 'Immutable append-only state-change audit trail. corpus_build_ref (F3) is the WEIGHT_EPOCH / CorpusManifest identity the deciding evaluation read from - invariant 2''s re-evaluation guard compares against it. Hypertable on triggered_at (same storage engine as config_history / llm_calls, this project''s other append-only audit trails).';


