--
-- Name: bar_content_digest; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_content_digest (
    symbol text NOT NULL,
    timeframe text NOT NULL,
    range_start timestamp with time zone NOT NULL,
    range_end timestamp with time zone NOT NULL,
    digest text NOT NULL,
    algorithm text NOT NULL,
    rule_version text NOT NULL,
    n_rows integer NOT NULL,
    batch_id uuid,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bar_content_digest_n_rows_check CHECK ((n_rows >= 0))
);


ALTER TABLE public.bar_content_digest OWNER TO postgres;

--
-- Name: TABLE bar_content_digest; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_content_digest IS 'Append-only bar content digests per (symbol, timeframe, calendar month) for 5m, 15m and 1h (migration 383, D-07): sha256-bars-v1 over values plus flag state, computed by src/intelligence/bars/digest.py. The rule version sits beside the digest and is deliberately not an input to it. Phase 186 revision detection reads bar_content_digest_current, never this table directly. Permanent: UPDATE, DELETE and TRUNCATE raise.';


--
-- Name: bar_content_digest_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bar_content_digest_current AS
 SELECT DISTINCT ON (symbol, timeframe, range_start) symbol,
    timeframe,
    range_start,
    range_end,
    digest,
    algorithm,
    rule_version,
    n_rows,
    batch_id,
    computed_at
   FROM public.bar_content_digest
  ORDER BY symbol, timeframe, range_start, computed_at DESC;


ALTER VIEW public.bar_content_digest_current OWNER TO postgres;

--
-- Name: VIEW bar_content_digest_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.bar_content_digest_current IS 'Latest bar_content_digest row per (symbol, timeframe, range_start): the revision-detection surface phase 186 consumes and bar_derivation --stage grid --changed-only compares against.';


--
-- Name: bar_derivation_batch; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_derivation_batch (
    batch_id uuid NOT NULL,
    stage text NOT NULL,
    rule_version text NOT NULL,
    code_commit text NOT NULL,
    apr_snapshot jsonb NOT NULL,
    n_symbols integer,
    status text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT bar_derivation_batch_stage_check CHECK ((stage = ANY (ARRAY['scrub'::text, 'grid'::text, 'daily'::text, 'seam_audit'::text, 'listing_venue'::text, 'legacy'::text, 'tradier'::text]))),
    CONSTRAINT bar_derivation_batch_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'partial'::text, 'failed'::text])))
);


ALTER TABLE public.bar_derivation_batch OWNER TO postgres;

--
-- Name: TABLE bar_derivation_batch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_derivation_batch IS 'Provenance for every derivation-side run (scrub, grid, daily, seam audit, listing venue, legacy imports, Tradier daily loads): stage, rule version, code commit, APR snapshot, status. Single writer role bar_derivation_writer.';


--
-- Name: bar_hold; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_hold (
    hold_id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    reason text NOT NULL,
    factor double precision,
    first_affected_date date,
    last_affected_date date,
    action_id uuid,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_by text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    releases uuid,
    CONSTRAINT bar_hold_factor_check CHECK (((factor IS NULL) OR ((factor > (0)::double precision) AND (factor <> 'Infinity'::double precision) AND (factor <> 'NaN'::double precision)))),
    CONSTRAINT bar_hold_reason_check CHECK ((reason = ANY (ARRAY['unclassified_rescale'::text, 'slot_coverage_gap'::text, 'release'::text]))),
    CONSTRAINT bar_hold_timeframe_check CHECK ((timeframe = ANY (ARRAY['1d'::text, '5m'::text]))),
    CONSTRAINT ck_bar_hold_detail_object CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT ck_bar_hold_release CHECK (((reason = 'release'::text) = (releases IS NOT NULL))),
    CONSTRAINT ck_bar_hold_rescale CHECK (((reason <> 'unclassified_rescale'::text) OR ((factor IS NOT NULL) AND (first_affected_date IS NOT NULL) AND (last_affected_date IS NOT NULL) AND (first_affected_date <= last_affected_date))))
);


ALTER TABLE public.bar_hold OWNER TO postgres;

--
-- Name: TABLE bar_hold; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_hold IS 'Held names (migration 461, plan 185-51; reason slot_coverage_gap by 552, todo 565): a name is held for a timeframe while bar_hold_current has a row for it, and its canonical bars stay as they are. Reason unclassified_rescale: a constant vendor rescale whose factor is no recognised split ratio (never a corporate_action row). Reason slot_coverage_gap: a 5m name whose worst-year slot_coverage share sits below the threshold because Alpaca SIP has no bar for a slot in which no trade printed (todo 565); the failing share, threshold and verdict time are the detail. The daily stage skips held names, D7 reports them. One writer: services/bar_hold.py under bar_derivation_writer. Append-only; a release is a new row whose releases names the hold.';


--
-- Name: bar_hold_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bar_hold_current AS
 SELECT hold_id,
    symbol,
    timeframe,
    reason,
    factor,
    first_affected_date,
    last_affected_date,
    action_id,
    detail,
    recorded_by,
    recorded_at,
    releases
   FROM public.bar_hold h
  WHERE ((reason <> 'release'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.bar_hold r
          WHERE (r.releases = h.hold_id)))));


ALTER VIEW public.bar_hold_current OWNER TO postgres;

--
-- Name: VIEW bar_hold_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.bar_hold_current IS 'Open holds: bar_hold rows that are not releases and that no release names (migration 461).';


--
-- Name: bar_quality_flag; Type: TABLE; Schema: public; Owner: postgres
