--
-- Name: bar_session_choice; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_session_choice (
    symbol text NOT NULL,
    timeframe text NOT NULL,
    session_date date NOT NULL,
    vendor text NOT NULL,
    ranking text[] NOT NULL,
    complete boolean NOT NULL,
    n_slots integer NOT NULL,
    n_vendor_slots integer NOT NULL,
    n_grid_slots integer,
    n_vendor_grid_slots integer,
    dropped timestamp with time zone[] DEFAULT '{}'::timestamp with time zone[] NOT NULL,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    n_primary_grid_slots integer,
    CONSTRAINT bar_session_choice_n_grid_slots_check CHECK ((n_grid_slots >= 0)),
    CONSTRAINT bar_session_choice_n_primary_grid_slots_check CHECK ((n_primary_grid_slots >= 0)),
    CONSTRAINT bar_session_choice_n_slots_check CHECK ((n_slots >= 0)),
    CONSTRAINT bar_session_choice_n_vendor_grid_slots_check CHECK ((n_vendor_grid_slots >= 0)),
    CONSTRAINT bar_session_choice_n_vendor_slots_check CHECK ((n_vendor_slots >= 0)),
    CONSTRAINT bar_session_choice_timeframe_check CHECK ((timeframe = ANY (ARRAY['1m'::text, '5m'::text, '4h'::text])))
);


ALTER TABLE public.bar_session_choice OWNER TO postgres;

--
-- Name: TABLE bar_session_choice; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_session_choice IS 'Sessions selection did not take plainly (ranked-first vendor, complete, every calendar slot): the vendor it took the session from, whether any ranked vendor held it whole, the slot counts against the NYSE regular-hours grid, and the slots left out. Sole writer: services/bar_selection.py select_and_write. Migration 480.';


--
-- Name: COLUMN bar_session_choice.complete; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_session_choice.complete IS 'True when some ranked vendor held every regular-hours slot any ranked vendor held.';


--
-- Name: COLUMN bar_session_choice.n_grid_slots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_session_choice.n_grid_slots IS 'The calendar''s regular-hours slots of the session. NULL on a timeframe with a grid (5m): the calendar grid does not apply, because no ranked vendor holds a stamp on it (IBKR opened 14:30 UTC on 2006-12-27 where the calendar says 14:32) or the date is no NYSE session; completeness is then judged on the vendors'' own slots. Migration 485.';


--
-- Name: COLUMN bar_session_choice.dropped; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_session_choice.dropped IS 'Slots another ranked vendor held that the session rule left out (canonical retracted).';


--
-- Name: COLUMN bar_session_choice.n_primary_grid_slots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_session_choice.n_primary_grid_slots IS 'The ranked-first vendor''s regular-hours slots of the session: 0 is a fallback by absence (the primary held nothing), more is a shortfall. NULL without a grid. Migration 484.';


--
-- Name: bar_source_policy; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bar_source_policy (
    policy_id uuid DEFAULT gen_random_uuid() NOT NULL,
    timeframe text NOT NULL,
    symbol text,
    valid_from date NOT NULL,
    valid_to date,
    ingress_mode text NOT NULL,
    primary_source text NOT NULL,
    fallback_source text,
    reason text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    retired_at timestamp with time zone,
    retired_reason text,
    CONSTRAINT bar_source_policy_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT bar_source_policy_check1 CHECK ((fallback_source IS DISTINCT FROM primary_source)),
    CONSTRAINT bar_source_policy_check2 CHECK (((ingress_mode = 'derived'::text) = (primary_source = 'derived'::text))),
    CONSTRAINT bar_source_policy_ingress_mode_check CHECK ((ingress_mode = ANY (ARRAY['observed'::text, 'direct'::text, 'derived'::text]))),
    CONSTRAINT bar_source_policy_timeframe_check CHECK ((timeframe = ANY (ARRAY['1d'::text, '5m'::text, '1m'::text, '15m'::text, '1h'::text, '4h'::text]))),
    CONSTRAINT ck_bar_source_policy_closed_at CHECK (((closed_at IS NULL) OR ((valid_to IS NOT NULL) AND (closed_at >= recorded_at)))),
    CONSTRAINT ck_bar_source_policy_retired CHECK (((retired_at IS NULL) = (retired_reason IS NULL)))
);


ALTER TABLE public.bar_source_policy OWNER TO postgres;

--
-- Name: TABLE bar_source_policy; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bar_source_policy IS 'The only place a bar source choice lives (migration 446, plan 185-36, data layer integrity design section 2): per (timeframe, symbol or NULL default, [valid_from, valid_to)) the ingress mode, primary and fallback source. Decisions, not measurements. Append-only: the only update closes an open row; DELETE and TRUNCATE raise. Rows never overlap per series. d2-v2 raises on a date no row covers.';


--
-- Name: COLUMN bar_source_policy.closed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_source_policy.closed_at IS 'When the row was closed (valid_to set by the one allowed UPDATE); stamped by the append-only trigger, never by a writer (migration 460, plan 185-50). NULL on an open row, on a row inserted closed, and on a row closed before migration 460 (except the three 185-49 closes, backfilled). The daily stage reads GREATEST(recorded_at, closed_at) as when the row changed.';


--
-- Name: COLUMN bar_source_policy.retired_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.bar_source_policy.retired_at IS 'When the row was taken out of force (migration 520); the row and its history stay.';


--
-- Name: bar_source_policy_changes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bar_source_policy_changes AS
 SELECT policy_id,
    timeframe,
    symbol,
    valid_from,
    valid_to,
    recorded_at,
    closed_at,
    retired_at
   FROM public.bar_source_policy;


ALTER VIEW public.bar_source_policy_changes OWNER TO postgres;

--
-- Name: VIEW bar_source_policy_changes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.bar_source_policy_changes IS 'Every bar_source_policy row with its change stamps, retired rows included (migration 520): for change detection only; selection reads bar_source_policy_current.';


--
-- Name: bar_source_policy_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bar_source_policy_current AS
 SELECT policy_id,
    timeframe,
    symbol,
    valid_from,
    valid_to,
    ingress_mode,
    primary_source,
    fallback_source,
    reason,
    evidence,
    recorded_at,
    closed_at
   FROM public.bar_source_policy
  WHERE (retired_at IS NULL);


ALTER VIEW public.bar_source_policy_current OWNER TO postgres;

--
-- Name: VIEW bar_source_policy_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.bar_source_policy_current IS 'The bar_source_policy rows in force (not retired; migration 520). Every reader reads this view.';


--
-- Name: ohlcv_load; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_load (
    load_id uuid NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    source text NOT NULL,
    requested_start date NOT NULL,
    requested_end date NOT NULL,
    outcome text NOT NULL,
    n_bars integer NOT NULL,
    n_new integer DEFAULT 0 NOT NULL,
    n_changed integer DEFAULT 0 NOT NULL,
    first_bar date,
    last_bar date,
    detail text,
    caller text NOT NULL,
    loaded_at timestamp with time zone DEFAULT now() NOT NULL,
    batch_id uuid,
    n_unchanged integer,
    n_removed integer,
    destination text DEFAULT 'market_data_ohlcv'::text NOT NULL,
    n_archived integer DEFAULT 0 NOT NULL,
    n_superseded integer DEFAULT 0 NOT NULL,
    CONSTRAINT ohlcv_load_destination_check CHECK ((destination = ANY (ARRAY['d1'::text, 'market_data_ohlcv'::text, 'archive'::text, 'raw'::text]))),
    CONSTRAINT ohlcv_load_n_bars_check CHECK ((n_bars >= 0)),
    CONSTRAINT ohlcv_load_n_changed_check CHECK ((n_changed >= 0)),
    CONSTRAINT ohlcv_load_n_new_check CHECK ((n_new >= 0)),
    CONSTRAINT ohlcv_load_n_removed_check CHECK ((n_removed >= 0)),
    CONSTRAINT ohlcv_load_n_superseded_check CHECK ((n_superseded >= 0)),
    CONSTRAINT ohlcv_load_n_unchanged_check CHECK ((n_unchanged >= 0)),
    CONSTRAINT ohlcv_load_outcome_check CHECK ((outcome = ANY (ARRAY['loaded'::text, 'short_history'::text, 'no_data'::text, 'failed'::text, 'gated'::text, 'applied'::text, 'refused'::text]))),
    CONSTRAINT ohlcv_load_timeframe_check CHECK ((timeframe = ANY (ARRAY['1d'::text, '5m'::text, '1m'::text, '15m'::text, '1h'::text, '4h'::text])))
);


ALTER TABLE public.ohlcv_load OWNER TO postgres;

--
-- Name: COLUMN ohlcv_load.n_archived; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_load.n_archived IS 'refused chunk: served rows routed to ohlcv_intraday_raw_archive in the refusal transaction (todo 528); 0 otherwise';


--
-- Name: COLUMN ohlcv_load.n_superseded; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_load.n_superseded IS 'Offered rows older than the stored row''s serve time: logged as superseded revisions, raw unchanged (last-wins by serve time). Migration 485.';


--
-- Name: ohlcv_request; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_request (
    request_id uuid NOT NULL,
    fetch_run_id uuid NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    source text NOT NULL,
    route text NOT NULL,
    what_to_show text NOT NULL,
    primary_exchange text,
    window_start timestamp with time zone,
    window_end timestamp with time zone NOT NULL,
    ib_req_id integer,
    outcome text NOT NULL,
    error_code integer,
    error_text text,
    n_bars integer NOT NULL,
    client_id integer,
    caller text NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    answered_at timestamp with time zone NOT NULL,
    content_digest text,
    partial_bars jsonb,
    CONSTRAINT ohlcv_request_content_digest_check CHECK (((content_digest IS NULL) OR (content_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ohlcv_request_n_bars_check CHECK ((n_bars >= 0)),
    CONSTRAINT ohlcv_request_outcome_check CHECK ((outcome = ANY (ARRAY['bars'::text, 'no_data'::text, 'timeout'::text, 'failed'::text, 'legacy_import'::text]))),
    CONSTRAINT ohlcv_request_route_check CHECK ((route ~ '^[A-Z_]{2,16}$'::text)),
    CONSTRAINT ohlcv_request_source_check CHECK ((source = ANY (ARRAY['ibkr'::text, 'tradier'::text, 'alpaca'::text]))),
    CONSTRAINT ohlcv_request_what_to_show_check CHECK ((what_to_show = ANY (ARRAY['TRADES'::text, 'ADJUSTED_LAST'::text, '1Min'::text, '5Min'::text, '1Day'::text])))
);


ALTER TABLE public.ohlcv_request OWNER TO postgres;

--
-- Name: TABLE ohlcv_request; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ohlcv_request IS 'Append-only log of every IBKR history request and its outcome (migration 380, D1). One row per request, any timeframe; request_id is generated by the provider. TRADES and ADJUSTED_LAST pair only within one fetch_run_id. Permanent: UPDATE, DELETE and TRUNCATE raise.';


--
-- Name: COLUMN ohlcv_request.content_digest; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_request.content_digest IS 'sha256-bars-v1 digest (src/intelligence/bars/digest.py) of the rows the request''s chunk stored; NULL when the request stored nothing (plan 185-39, design section 3).';


--
-- Name: COLUMN ohlcv_request.partial_bars; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_request.partial_bars IS 'Bars this answer served that were not complete vendor answers (straddling the request end, still forming at answered_at, or a session-closing bar answered before the settle delay), as a JSON array of {t, o, h, l, c, v}; they were not offered to ohlcv_raw. NULL when none were dropped or the row predates the rule. The gap planner treats these slots as not answered. Migration 479.';


--
-- Name: canonical_bar_lineage; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.canonical_bar_lineage AS
 SELECT m.symbol,
    m.timeframe,
    m."timestamp",
    d.rule_version,
    o.request_ids,
    d.batch_id,
    d.computed_at AS derived_at
   FROM ((public.market_data_ohlcv m
     LEFT JOIN ( SELECT r.symbol,
            r."timestamp" AS session_ts,
            r.vendor,
            r.kind,
            r.open,
            r.high,
            r.low,
            r.close,
            r.volume,
            ARRAY[r.request_id] AS request_ids
           FROM (public.ohlcv_raw r
             JOIN public.ohlcv_request q ON ((q.request_id = r.request_id)))
          WHERE ((r.timeframe = '1d'::text) AND (((r.vendor = 'tradier'::text) AND (r.kind = 'consolidated'::text)) OR ((r.vendor = 'ibkr'::text) AND (r.kind = 'smart_trades'::text))) AND (q.caller !~~ 'test-%'::text))
        UNION ALL
         SELECT r.symbol,
            ((((r."timestamp" AT TIME ZONE 'America/New_York'::text))::date)::timestamp without time zone AT TIME ZONE 'UTC'::text) AS timezone,
            r.vendor,
            r.kind,
            r.open,
            r.high,
            r.low,
            r.close,
            r.volume,
            ARRAY[r.request_id] AS "array"
           FROM (public.ohlcv_raw r
             JOIN public.ohlcv_load l ON ((l.load_id = r.load_id)))
          WHERE ((r.timeframe = '1d'::text) AND (r.vendor = 'alpaca'::text) AND (r.kind = 'sip_rth'::text) AND (l.caller !~~ 'test-%'::text))) o ON (((o.symbol = m.symbol) AND (o.session_ts = m."timestamp") AND
        CASE
            WHEN ((m.vendor = 'tradier'::text) AND (m.kind = 'consolidated'::text)) THEN ((o.vendor = 'tradier'::text) AND (o.kind = 'consolidated'::text))
            WHEN ((m.vendor = 'ibkr'::text) AND (m.kind = ANY (ARRAY['named'::text, 'fallback'::text]))) THEN ((o.vendor = 'ibkr'::text) AND (o.kind = 'smart_trades'::text))
            WHEN ((m.vendor = 'alpaca'::text) AND (m.kind = 'sip_rth'::text)) THEN ((o.vendor = 'alpaca'::text) AND (o.kind = 'sip_rth'::text))
            ELSE false
        END AND (NOT (o.open IS DISTINCT FROM m.open)) AND (NOT (o.high IS DISTINCT FROM m.high)) AND (NOT (o.low IS DISTINCT FROM m.low)) AND (NOT (o.close IS DISTINCT FROM m.close)) AND (NOT (o.volume IS DISTINCT FROM m.volume)))))
     LEFT JOIN LATERAL ( SELECT c.rule_version,
            c.batch_id,
            c.computed_at
           FROM public.bar_content_digest c
          WHERE ((c.symbol = m.symbol) AND (c.timeframe = '1d'::text) AND (c.range_start <= m."timestamp") AND (m."timestamp" < c.range_end))
          ORDER BY c.range_start DESC, c.computed_at DESC
         LIMIT 1) d ON (true))
  WHERE (m.timeframe = '1d'::text);


