--
-- Name: concept_research_stage; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.concept_research_stage AS
 WITH attempts AS (
         SELECT research_run.concept_id,
            count(*) AS attempts,
            count(*) FILTER (WHERE (research_run.status = 'started'::text)) AS started,
            count(*) FILTER (WHERE ((research_run.status = ANY (ARRAY['completed'::text, 'failed'::text])) AND (research_run.kind <> 'legacy_verdict'::text))) AS tested,
            count(*) FILTER (WHERE (research_run.status = ANY (ARRAY['refused'::text, 'guard_failed'::text]))) AS refused,
            count(*) FILTER (WHERE (research_run.kind = 'legacy_verdict'::text)) AS legacy,
            max(research_run.started_at) AS last_attempt_at
           FROM public.research_run
          GROUP BY research_run.concept_id
        ), recipes AS (
         SELECT concept_recipe.concept_id,
            count(*) AS recipe_versions,
            max(concept_recipe.version) AS latest_version,
            max(concept_recipe.created_at) AS last_recipe_at
           FROM public.concept_recipe
          GROUP BY concept_recipe.concept_id
        )
 SELECT c.concept_id,
    c.domain,
    c.name,
    c.status,
        CASE
            WHEN ((c.domain = 'book'::text) AND (c.status = 'active'::text)) THEN 'confirmed'::text
            WHEN ((c.domain = 'book'::text) AND (c.status = 'shadow_only'::text)) THEN 'frozen'::text
            WHEN (c.status = 'deprecated'::text) THEN 'refused'::text
            WHEN (COALESCE(a.started, (0)::bigint) > 0) THEN 'registered'::text
            WHEN (COALESCE(a.tested, (0)::bigint) > 0) THEN 'tested'::text
            WHEN ((COALESCE(a.refused, (0)::bigint) > 0) AND (NOT COALESCE((r.last_recipe_at > a.last_attempt_at), false))) THEN 'refused'::text
            WHEN (COALESCE(r.recipe_versions, (0)::bigint) > 0) THEN 'specified'::text
            WHEN (COALESCE(a.legacy, (0)::bigint) > 0) THEN 'refused'::text
            ELSE 'idea'::text
        END AS stage,
    COALESCE(r.recipe_versions, (0)::bigint) AS recipe_versions,
    r.latest_version,
    COALESCE(a.attempts, (0)::bigint) AS attempts,
    COALESCE(a.started, (0)::bigint) AS started,
    COALESCE(a.tested, (0)::bigint) AS tested,
    COALESCE(a.refused, (0)::bigint) AS refused,
    COALESCE(a.legacy, (0)::bigint) AS legacy_verdicts
   FROM ((public.concept_registry c
     LEFT JOIN attempts a USING (concept_id))
     LEFT JOIN recipes r USING (concept_id));


ALTER VIEW public.concept_research_stage OWNER TO postgres;

--
-- Name: VIEW concept_research_stage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.concept_research_stage IS 'One row per concept: its research stage (idea, specified, registered, tested, refused, frozen, confirmed), derived from concept_registry, concept_recipe and research_run. Nothing stores the stage (design 10.2.4).';


