-- Name: controlled_vocabulary; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.controlled_vocabulary (
    namespace text NOT NULL,
    code text NOT NULL,
    label text NOT NULL,
    description text,
    sort_order integer DEFAULT 0 NOT NULL,
    is_deprecated boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.controlled_vocabulary OWNER TO postgres;

--
-- Name: TABLE controlled_vocabulary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.controlled_vocabulary IS 'Authoritative flat vocabulary registry: one row per (namespace, code) symbolic taxonomy entry (e.g. regime_hmm/trending_up, timeframe/5m). Rows here are definitional - a code either exists in a namespace or it does not, with no confidence/weight/evidence attached. This is explicitly distinct from the symbol-to-tag assignment system (migration 227), whose rows are confidence-weighted, falsifiable-hypothesis entity assignments with provenance and evidence columns - a different epistemic kind of row entirely, not merely a different schema. Do not add weight/confidence/evidence columns here; that need belongs in a membership table like the existing tag-assignment table, not in this definitional registry.';


--
-- Name: corporate_action; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.corporate_action (
    action_id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    action_type text NOT NULL,
    effective_date date NOT NULL,
    factor double precision NOT NULL,
    inferred_by text NOT NULL,
    evidence_request_ids uuid[] NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    supersedes uuid,
    batch_id uuid,
    CONSTRAINT ck_corporate_action_void_supersedes CHECK (((action_type <> 'void'::text) OR (supersedes IS NOT NULL))),
    CONSTRAINT corporate_action_action_type_check CHECK ((action_type = ANY (ARRAY['split'::text, 'reverse_split'::text, 'void'::text]))),
    CONSTRAINT corporate_action_factor_check CHECK (((factor > (0)::double precision) AND (factor <> 'Infinity'::double precision) AND (factor <> 'NaN'::double precision))),
    CONSTRAINT corporate_action_inferred_by_check CHECK ((inferred_by = ANY (ARRAY['seam_audit'::text, 'nightly_overlap'::text, 'tradier_refetch'::text, 'operator'::text, 'calendar_audit'::text])))
);


ALTER TABLE public.corporate_action OWNER TO postgres;

--
-- Name: TABLE corporate_action; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.corporate_action IS 'Append-only record of splits and reverse splits (migration 400, D-21/D-24). factor is stored/fresh on the old scale (2.0 = 2-for-1, 0.125 = 1-for-8); effective_date is the last day on the old scale. evidence_request_ids name the ohlcv_request rows behind the record. Permanent: UPDATE, DELETE and TRUNCATE raise; corrections are new rows with supersedes, a void row retracts the row it supersedes (migration 461), inferred_by operator marks a by-hand correction (ops_split_detect.py).';


--
-- Name: corporate_action_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.corporate_action_current AS
 SELECT action_id,
    symbol,
    action_type,
    effective_date,
    factor,
    inferred_by,
    evidence_request_ids,
    detail,
    recorded_at,
    supersedes,
    batch_id
   FROM public.corporate_action ca
  WHERE ((action_type <> 'void'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.corporate_action newer
          WHERE (newer.supersedes = ca.action_id)))));


ALTER VIEW public.corporate_action_current OWNER TO postgres;

--
-- Name: VIEW corporate_action_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.corporate_action_current IS 'corporate_action rows that no later row supersedes, void rows excluded (migrations 400, 461).';


--
-- Name: dividend_date_dispute; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dividend_date_dispute (
    symbol text NOT NULL,
    first_date date NOT NULL,
    last_date date NOT NULL,
    dates_by_source jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    fetch_run_id uuid,
    CONSTRAINT dividend_date_dispute_span CHECK ((((last_date - first_date) >= 1) AND ((last_date - first_date) <= 5)))
);


ALTER TABLE public.dividend_date_dispute OWNER TO postgres;

--
-- Name: TABLE dividend_date_dispute; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dividend_date_dispute IS 'One dividend reported by both sources with disagreeing ex-dates (D-23, migration 403): first_date/last_date are the ordered span (1-5 days apart), dates_by_source maps each source name to the ex-date it reported, fetch_run_id the D1 run the IBKR side was derived from when the dispute was recorded. Returns spanning [first_date - 1 session, last_date] are unknown to the research reader. First recording wins: the writer uses ON CONFLICT DO NOTHING, so recorded_at is when the dispute was first seen.';


--
-- Name: COLUMN dividend_date_dispute.dates_by_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.dividend_date_dispute.dates_by_source IS 'JSON object, one key per source (ibkr_adjusted_last_ratio, yahoo), value the ISO ex-date that source reported.';


--
-- Name: dividend_event_coverage; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dividend_event_coverage (
    symbol text NOT NULL,
    source text NOT NULL,
    covered_from date NOT NULL,
    covered_to date NOT NULL,
    checked_at timestamp with time zone NOT NULL,
    CONSTRAINT dividend_event_coverage_check CHECK ((covered_to >= covered_from)),
    CONSTRAINT dividend_event_coverage_source_check CHECK ((source = ANY (ARRAY['yahoo'::text, 'ibkr_adjusted_last_ratio'::text])))
);


ALTER TABLE public.dividend_event_coverage OWNER TO postgres;

--
-- Name: TABLE dividend_event_coverage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dividend_event_coverage IS 'Contiguous span of ex-dates each source examined per symbol. Outside the yahoo span the dividend history is unknown, not zero.';


--
-- Name: dividend_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dividend_events (
    symbol text NOT NULL,
    ex_date date NOT NULL,
    source text NOT NULL,
    amount double precision NOT NULL,
    prev_close double precision NOT NULL,
    compute_version text NOT NULL,
    derived_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dividend_events_amount_check CHECK ((amount > (0)::double precision)),
    CONSTRAINT dividend_events_finite CHECK (((amount <> 'NaN'::double precision) AND (amount <> 'Infinity'::double precision) AND (prev_close <> 'NaN'::double precision) AND (prev_close <> 'Infinity'::double precision))),
    CONSTRAINT dividend_events_prev_close_check CHECK ((prev_close > (0)::double precision)),
    CONSTRAINT dividend_events_source_check CHECK ((source = ANY (ARRAY['yahoo'::text, 'ibkr_adjusted_last_ratio'::text])))
);


ALTER TABLE public.dividend_events OWNER TO postgres;

--
-- Name: TABLE dividend_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dividend_events IS 'Per-share cash distributions by ex-date and source (todo 428). Read amount / prev_close (the yield on the ex-date): both are in the split units of the day the row was derived. First derivation wins; re-derivations never overwrite. Readers use dividend_events_reconciled, not this table.';


--
-- Name: dividend_events_reconciled; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.dividend_events_reconciled AS
 SELECT symbol,
    ex_date,
    max((amount / prev_close)) FILTER (WHERE (source = 'yahoo'::text)) AS yahoo_yield,
    max((amount / prev_close)) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text)) AS ibkr_yield,
    COALESCE(max((amount / prev_close)) FILTER (WHERE (source = 'yahoo'::text)), max((amount / prev_close)) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text))) AS dividend_yield,
    max(prev_close) FILTER (WHERE (source = 'ibkr_adjusted_last_ratio'::text)) AS ibkr_prev_close
   FROM public.dividend_events
  GROUP BY symbol, ex_date;


ALTER VIEW public.dividend_events_reconciled OWNER TO postgres;

--
-- Name: VIEW dividend_events_reconciled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.dividend_events_reconciled IS 'One row per (symbol, ex_date): each source''s yield (NULL where it lacks the event), IBKR''s prior close (for its rounding bound, 0.02 / close) and dividend_yield, a naive Yahoo-first default. Facts only: research readers resolve agreement, dispute and single-source events with research/dividends.resolve_event, not dividend_yield (todo 428).';


