ALTER TABLE public.feature_vectors OWNER TO postgres;

--
-- Name: TABLE feature_vectors; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.feature_vectors IS 'The feature table, one row per (symbol, tf, bar_ts), columns derived from the kernel registry. Sole writer: bulk_load for the rebuild writer (services/backfill_feature_factory.py). Lineage = provenance_batch records; no per-row provenance column (D-34/D-24). No compression policy (bulk_load refuses ranges a policy covers); the writer compresses chunks no pending unit can still write into.';


--
-- Name: gate_evaluations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.gate_evaluations (
    eval_id text,
    gate_id text NOT NULL,
    result text NOT NULL,
    evidence jsonb NOT NULL,
    run_ts timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.gate_evaluations OWNER TO postgres;

--
-- Name: instrument_annotations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_annotations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    annotation_type text NOT NULL,
    content text NOT NULL,
    source text NOT NULL,
    model_id text,
    confidence double precision,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT instrument_annotations_annotation_type_check CHECK ((annotation_type = ANY (ARRAY['thesis'::text, 'signal_context'::text, 'ai_insight'::text, 'regime_note'::text]))),
    CONSTRAINT instrument_annotations_confidence_check CHECK (((confidence >= (0.0)::double precision) AND (confidence <= (1.0)::double precision))),
    CONSTRAINT instrument_annotations_source_check CHECK ((source = ANY (ARRAY['human'::text, 'ai'::text])))
);


ALTER TABLE public.instrument_annotations OWNER TO postgres;

--
-- Name: instrument_classification; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_classification (
    symbol text NOT NULL,
    scheme text NOT NULL,
    code text NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    source_ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT instrument_classification_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from)))
);


ALTER TABLE public.instrument_classification OWNER TO postgres;

--
-- Name: TABLE instrument_classification; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.instrument_classification IS 'Reference data, migration-seeded initially. Membership stores the deepest known node only; ancestors are derived via classification_node.path. Append-only in effect: a reclassification closes the prior row (valid_to) and inserts a new row, never an UPDATE of code on an existing row. symbol has ON DELETE RESTRICT (not CASCADE): instruments are deactivated, not deleted, and a delete attempt must crash loudly rather than silently destroy point-in-time classification history.';


--
-- Name: instrument_metadata; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_metadata (
    symbol text NOT NULL,
    listing_date date,
    underlying_index text,
    issuer text,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.instrument_metadata OWNER TO postgres;

--
-- Name: instrument_tags; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instrument_tags (
    symbol text NOT NULL,
    tag text NOT NULL,
    weight double precision DEFAULT 1.0 NOT NULL,
    source text DEFAULT 'human'::text NOT NULL,
    evidence jsonb,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    loading double precision,
    p_value double precision,
    bh_adjusted_p double precision,
    passes_fdr boolean,
    consecutive_fails integer DEFAULT 0 NOT NULL,
    sample_n integer,
    estimated_at timestamp with time zone,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    partial_loading double precision,
    partial_loading_ci_low double precision,
    incremental_r2 double precision,
    sign_stable_windows integer,
    sign_stable_windows_total integer,
    null_arm_p_value double precision,
    null_arm_bh_p double precision,
    materiality_sample_n integer,
    passes_materiality boolean,
    discovery_state text,
    first_measured_at timestamp with time zone,
    CONSTRAINT instrument_tags_discovery_state_check CHECK (((discovery_state IS NULL) OR (discovery_state = ANY (ARRAY['pending_oos'::text, 'confirmed'::text])))),
    CONSTRAINT instrument_tags_source_check CHECK ((source = ANY (ARRAY['human'::text, 'empirical'::text, 'ai'::text]))),
    CONSTRAINT instrument_tags_weight_check CHECK (((weight >= (0.0)::double precision) AND (weight <= (1.0)::double precision)))
);


ALTER TABLE public.instrument_tags OWNER TO postgres;

--
-- Name: COLUMN instrument_tags.partial_loading; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.partial_loading IS 'Pass 4: OLS beta of the (symbol, tag) loading after orthogonalizing against the control factor set (control_factor_series). The materiality-filtered replacement for a raw, unconditioned loading.';


--
-- Name: COLUMN instrument_tags.partial_loading_ci_low; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.partial_loading_ci_low IS 'Pass 4: lower bound of the confidence interval around partial_loading (Codex''s R-05 lower-CI gate). A real column and a real gate, not dropped.';


--
-- Name: COLUMN instrument_tags.incremental_r2; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.incremental_r2 IS 'Pass 4: incremental R-squared contributed by this tag''s factor_series beyond the control set alone -- the explanatory-power component of the materiality gate.';


--
-- Name: COLUMN instrument_tags.sign_stable_windows; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.sign_stable_windows IS 'Pass 4: count of rolling measurement windows (out of sign_stable_windows_total) in which partial_loading''s sign matched the run-level sign -- the D-06 sign-stability component.';


--
-- Name: COLUMN instrument_tags.sign_stable_windows_total; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.sign_stable_windows_total IS 'Pass 4: total number of rolling measurement windows evaluated for sign stability. Denominator for sign_stable_windows.';


--
-- Name: COLUMN instrument_tags.null_arm_p_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.null_arm_p_value IS 'Pass 4: raw p-value from the D-06 circular-shift null-arm control for this (symbol, tag) pair, before BH-FDR adjustment.';


--
-- Name: COLUMN instrument_tags.null_arm_bh_p; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.null_arm_bh_p IS 'Pass 4: Benjamini-Hochberg run-level FDR-adjusted null_arm_p_value.';


--
-- Name: COLUMN instrument_tags.materiality_sample_n; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.materiality_sample_n IS 'Pass 4''s own post-control-alignment observation count -- distinct from sample_n, which is Pass 1''s bivariate alignment count. The two counts measure different alignments and must not be conflated.';


--
-- Name: COLUMN instrument_tags.passes_materiality; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.passes_materiality IS 'Pass 4: the STATISTICAL gate only (R-04). Readers MUST additionally AND this with discovery_state = ''confirmed'' (the temporal gate, todo 125) and valid_to IS NULL (the expiry gate, todo 126) -- the three gates are stored separately, not collapsed, so a future per-consumer cutover can calibrate its own bar.';


--
-- Name: COLUMN instrument_tags.discovery_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.discovery_state IS 'todo 125: typed promotion of the discovery-state concept out of the evidence JSONB blob. NULL until TagCalibrator''s next run backfills it; otherwise ''pending_oos'' or ''confirmed''. The temporal gate referenced by passes_materiality''s comment (R-04).';


--
-- Name: COLUMN instrument_tags.first_measured_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instrument_tags.first_measured_at IS 'todo 125: typed promotion of the first-measurement timestamp out of the evidence JSONB blob -- the anchor discovery_oos_days counts forward from.';


--
-- Name: instrument_tags_active; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.instrument_tags_active AS
 SELECT symbol,
    tag,
    weight,
    source,
    evidence,
    assigned_at,
    loading,
    p_value,
    bh_adjusted_p,
    passes_fdr,
    consecutive_fails,
    sample_n,
    estimated_at,
    valid_from,
    valid_to,
    partial_loading,
    partial_loading_ci_low,
    incremental_r2,
    sign_stable_windows,
    sign_stable_windows_total,
    null_arm_p_value,
    null_arm_bh_p,
    materiality_sample_n,
    passes_materiality,
    discovery_state,
    first_measured_at
   FROM public.instrument_tags
  WHERE (valid_to IS NULL);


ALTER VIEW public.instrument_tags_active OWNER TO postgres;

--
-- Name: VIEW instrument_tags_active; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.instrument_tags_active IS 'todo 126: the required read path for any tag-membership query. Returns only unexpired (valid_to IS NULL) instrument_tags rows.';


--
-- Name: instruments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.instruments (
    symbol text NOT NULL,
    contract_details jsonb,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    base text NOT NULL,
    expiry date,
    compute_eligible boolean DEFAULT false NOT NULL,
    live_tradeable boolean DEFAULT false NOT NULL,
    compute_eligible_1d boolean DEFAULT false NOT NULL,
    universe_entry_date date,
    universe_cohort text,
    CONSTRAINT instruments_inactive_holds_no_eligibility CHECK (((is_active IS TRUE) OR (NOT (compute_eligible OR compute_eligible_1d OR live_tradeable))))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


ALTER TABLE public.instruments OWNER TO postgres;

--
-- Name: COLUMN instruments.is_active; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.is_active IS 'Dimension 1 of 3 (Phase 174 D-07): BACKFILL-ELIGIBLE. Retained with unchanged semantics; 37 call sites read it. Do not repurpose or rename.';


--
-- Name: COLUMN instruments.compute_eligible; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.compute_eligible IS 'Dimension 2 of 3 (Phase 174 D-07): COMPUTE-ELIGIBLE -- feature_factory / ic_engine / regime models consume this symbol. Defaults false (migration 352): every new row, from any insert path, starts ineligible and is promoted only by scripts/infrastructure/universe_expansion_promote_compute_eligible.py once COMPUTE_READY_PREDICATE_SQL holds -- fetch_complete AND non-zero tradeable rows at every timeframe in the APR compute stack (feature.factory.target_timeframes), never an any-one-timeframe test. An inactive row always holds false (migration 352 trigger + CHECK), so a
re-activated row starts ineligible.';


--
-- Name: COLUMN instruments.live_tradeable; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.live_tradeable IS 'Dimension 3 of 3 (Phase 174 D-07): LIVE-TRADEABLE -- eligible for IBKR live streaming (reqMktData / reqHistoricalData keepUpToDate=True), which is subject to the 80-simultaneous-subscription cap. Defaults false for every row; no row is live-eligible until a subscription whitelist is explicitly chosen.';


--
-- Name: COLUMN instruments.compute_eligible_1d; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.compute_eligible_1d IS 'Fourth eligibility dimension (Phase 174 D-09), independent of compute_eligible: this symbol''s 1d series is complete enough to participate in 1d-timeframe cross-sectional compute (dimension=''compute_1d'' in get_active_contracts()). Deliberately NOT implied by or narrowed from compute_eligible -- a symbol carrying compute_eligible_1d = true AND compute_eligible = false is the intended steady state for the Phase 174 D-09 down-cap cohort (1d bars only, no 5m/15m/1h history), not an inconsistency to be repaired. Defaults false for any newly inserted row until its own 1d backfill is measured complete via the same two-clause predicate (COMPUTE_READY_1D_PREDICATE_SQL in scripts/analysis/instrument_compute_eligibility_audit.py) used in this migration''s backfill UPDATE.';


--
-- Name: COLUMN instruments.universe_entry_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.universe_entry_date IS 'The UTC date the name entered the universe (the onboarding day). The manifest batch date where a manifest covers the name, else the row''s created_at date. Single writer: onboard_instrument() (todo 491). Not a vintage: vintage is a dated data span counted for a selection test (glossary).';


--
-- Name: COLUMN instruments.universe_cohort; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.instruments.universe_cohort IS 'The onboarding manifest cohort label naming the selection rule the row came from (config/universe/ manifests and README, e.g. ''spx'', ''r3k_501_1000''); NULL when no manifest names the instrument. Single writer: onboard_instrument() (todo 491).';


