    evidence jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    supersedes uuid,
    CONSTRAINT listing_end_evidence_check CHECK ((evidence <> '{}'::jsonb)),
    CONSTRAINT listing_end_reason_check CHECK ((reason = ANY (ARRAY['acquired'::text, 'merged'::text, 'taken_private'::text, 'delisted'::text])))
);


ALTER TABLE public.listing_end OWNER TO postgres;

--
-- Name: TABLE listing_end; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.listing_end IS 'Append-only record of a name''s last listed session (migration 518, todo 519). The name stays active and in every panel; freshness_1d judges it up to last_session. Corrections are new rows with supersedes; read through listing_end_current.';


--
-- Name: listing_end_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.listing_end_current AS
 SELECT listing_end_id,
    symbol,
    last_session,
    reason,
    evidence,
    recorded_at,
    supersedes
   FROM public.listing_end le
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.listing_end newer
          WHERE (newer.supersedes = le.listing_end_id))));


ALTER VIEW public.listing_end_current OWNER TO postgres;

--
-- Name: VIEW listing_end_current; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.listing_end_current IS 'listing_end rows that no later row supersedes (migration 518).';


