COMMENT ON VIEW public.market_data_ohlcv_scrub_input IS 'For the D2a scrub and D5 seam stages only: every traded bar (volume > 0, all vendors and kinds, quarantined bars included). Every other reader uses market_data_ohlcv_tradeable.';


--
-- Name: market_data_ohlcv_tradeable; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.market_data_ohlcv_tradeable AS
 SELECT "timestamp",
    symbol,
    timeframe,
    open,
    high,
    low,
    close,
        CASE
            WHEN (kind = 'venue'::text) THEN NULL::bigint
            ELSE volume
        END AS volume,
    vendor,
    kind,
    base,
    price_sanity_status
   FROM public.market_data_ohlcv
  WHERE ((volume > 0) AND (NOT (EXISTS ( SELECT 1
           FROM public.bar_quality_flag q
          WHERE (q.quarantine AND (q.symbol = market_data_ohlcv.symbol) AND (q.timeframe = market_data_ohlcv.timeframe) AND (q."timestamp" = market_data_ohlcv."timestamp"))))));


