--
-- Name: ohlcv_coverage; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_coverage (
    symbol text NOT NULL,
    timeframe text NOT NULL,
    earliest_timestamp timestamp with time zone,
    latest_timestamp timestamp with time zone,
    row_count bigint DEFAULT 0 NOT NULL,
    last_fetched_at timestamp with time zone,
    last_fetch_status text,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    provider text DEFAULT 'ibkr'::text NOT NULL,
    CONSTRAINT ohlcv_coverage_bounds_check CHECK (((earliest_timestamp IS NULL) OR (latest_timestamp IS NULL) OR (earliest_timestamp <= latest_timestamp))),
    CONSTRAINT ohlcv_coverage_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT ohlcv_coverage_provider_check CHECK ((provider <> ''::text)),
    CONSTRAINT ohlcv_coverage_row_count_check CHECK ((row_count >= 0)),
    CONSTRAINT ohlcv_coverage_status_check CHECK (((last_fetch_status IS NULL) OR (last_fetch_status = ANY (ARRAY['ok'::text, 'no_data'::text, 'error'::text]))))
);


ALTER TABLE public.ohlcv_coverage OWNER TO postgres;

--
-- Name: TABLE ohlcv_coverage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ohlcv_coverage IS 'Materialized coverage rollup per (symbol, timeframe) for the IBKR history fetcher queue (migration 432, phase 189 CD-03). Single writer services/ohlcv_coverage_writer.py, written in the same transaction as the bars and their ohlcv_request rows. Not a competing truth: ohlcv_request and the bar tables remain authoritative.';


--
-- Name: COLUMN ohlcv_coverage.symbol; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.symbol IS 'instruments.symbol (base symbol).';


--
-- Name: COLUMN ohlcv_coverage.timeframe; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.timeframe IS 'Bar timeframe code (1d, 1h, 15m, 5m, ...).';


--
-- Name: COLUMN ohlcv_coverage.earliest_timestamp; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.earliest_timestamp IS 'Earliest stored provider bar at the timeframe''s fetch destination; NULL when none stored.';


--
-- Name: COLUMN ohlcv_coverage.latest_timestamp; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.latest_timestamp IS 'Latest stored provider bar at the timeframe''s fetch destination; NULL when none stored.';


--
-- Name: COLUMN ohlcv_coverage.row_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.row_count IS 'Provider bars stored at the timeframe''s fetch destination (the archive for 15m/1h; tradeable rows, volume > 0, for grid timeframes).';


--
-- Name: COLUMN ohlcv_coverage.last_fetched_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.last_fetched_at IS 'When the latest fetch of this series was answered (or failed).';


--
-- Name: COLUMN ohlcv_coverage.last_fetch_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.last_fetch_status IS 'Outcome of the latest fetch: ok (bars), no_data (correct empty answer) or error.';


--
-- Name: COLUMN ohlcv_coverage.consecutive_failures; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.consecutive_failures IS 'Genuine failures (timeout, connection drop) since the last ok or no_data answer. no_data never increments it (CD-05). Past infra.backfill.max_consecutive_failures the series leaves the queue until reset with the fetcher''s --reset-failures flag.';


--
-- Name: COLUMN ohlcv_coverage.provider; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_coverage.provider IS 'Authoring fetch plane of this canonical-tier row (stored-state labeling, migration 464): which provider''s fetch path maintains the row, NOT a per-vendor provenance claim over the stored bars. Existing rows are ibkr-era stored-state rollups; Tradier-era 1d bounds and 449-lane bars ride under the ibkr label. Vendor claims live in ohlcv_load.source and the per-provider tier.';


--
-- Name: ohlcv_empty_history; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_empty_history (
