    CONSTRAINT ohlcv_restatement_flag_n_changed_check CHECK ((n_changed >= 0)),
    CONSTRAINT ohlcv_restatement_flag_n_stored_check CHECK ((n_stored >= 0)),
    CONSTRAINT ohlcv_restatement_flag_review_check CHECK (((reviewed_at IS NULL) = (reviewed_by IS NULL)))
);


ALTER TABLE public.ohlcv_restatement_flag OWNER TO postgres;

--
-- Name: TABLE ohlcv_restatement_flag; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ohlcv_restatement_flag IS 'Vendor loads the restatement detector flagged for review (D-191-N): the changed share and any basis-change signature (price_ratio, time_shift). The write itself landed last-wins; the old values are in ohlcv_revision under the same load_id. Writer: services/ohlcv_ingress_contract.py. Migration 481.';


--
-- Name: COLUMN ohlcv_restatement_flag.reviewed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_restatement_flag.reviewed_at IS 'Set with reviewed_by and review_note by scripts/ops/bars/ops_restatement_review.py. A flag with a basis-change signature and no review fails the selection gate. Migration 485.';


--
-- Name: ohlcv_revision; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ohlcv_revision (
    load_id uuid NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    old_open double precision NOT NULL,
    old_high double precision NOT NULL,
    old_low double precision NOT NULL,
    old_close double precision NOT NULL,
    old_volume bigint,
    old_source text NOT NULL,
    origin text DEFAULT 'load'::text NOT NULL,
    vendor text NOT NULL,
    kind text NOT NULL,
    request_id uuid,
    CONSTRAINT ohlcv_revision_origin_check CHECK ((origin = ANY (ARRAY['load'::text, 'archive_segment'::text, 'raw'::text, 'superseded'::text])))
);


ALTER TABLE public.ohlcv_revision OWNER TO postgres;

--
-- Name: COLUMN ohlcv_revision.origin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ohlcv_revision.origin IS 'raw: a value a later serve displaced (load_id = the replacing load, request_id = the old answer). superseded: an offer older than the stored row''s serve time, never written to raw (load_id and request_id = the offer). load and archive_segment: pre-191 history. Migration 485.';


--
-- Name: ohlcv_venue_head; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ohlcv_venue_head AS
 WITH smart_head AS (
         SELECT r.symbol,
            min(((r."timestamp" AT TIME ZONE 'UTC'::text))::date) AS smart_head_date
           FROM (public.ohlcv_raw r
             JOIN public.ohlcv_request q ON ((q.request_id = r.request_id)))
          WHERE ((r.timeframe = '1d'::text) AND (r.vendor = 'ibkr'::text) AND (r.kind = 'smart_trades'::text) AND (q.route = 'SMART'::text))
          GROUP BY r.symbol
        )
 SELECT v.symbol,
    upper(substr(v.kind, 7)) AS route,
    min(((v."timestamp" AT TIME ZONE 'UTC'::text))::date) AS first_bar_date,
    max(((v."timestamp" AT TIME ZONE 'UTC'::text))::date) AS last_bar_date,
    count(*) AS n_bars,
    sh.smart_head_date,
    ((max(((v."timestamp" AT TIME ZONE 'UTC'::text))::date) < sh.smart_head_date) OR (sh.smart_head_date IS NULL)) AS pre_move
   FROM (public.ohlcv_raw v
     LEFT JOIN smart_head sh ON ((sh.symbol = v.symbol)))
  WHERE ((v.timeframe = '1d'::text) AND (v.vendor = 'ibkr'::text) AND (v.kind ~~ 'venue\_%'::text))
  GROUP BY v.symbol, v.kind, sh.smart_head_date;


ALTER VIEW public.ohlcv_venue_head OWNER TO postgres;

--
-- Name: VIEW ohlcv_venue_head; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.ohlcv_venue_head IS 'Per (symbol, former IBKR venue route): first and last 1d bar date of the ibkr venue_<route> raw kind, raw row count, the symbol''s SMART head (earliest ibkr smart_trades 1d row a SMART request served; NULL if none), and pre_move = the route ends before the SMART head or there is no SMART head. The moved-name inventory (D-20 evidence, D-25 input). Over ohlcv_raw since migration 492 (plan 191-09).';


