--
-- Name: provenance_batch; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.provenance_batch (
    batch_key text NOT NULL,
    writer text NOT NULL,
    target_table text NOT NULL,
    time_column text NOT NULL,
    tf text NOT NULL,
    range_start timestamp with time zone NOT NULL,
    range_end timestamp with time zone NOT NULL,
    symbols text[] NOT NULL,
    symbols_hash text NOT NULL,
    code_key text NOT NULL,
    apr_hash text NOT NULL,
    apr_snapshot jsonb NOT NULL,
    input_digest text NOT NULL,
    row_count bigint,
    status text DEFAULT 'started'::text NOT NULL,
    attempts integer DEFAULT 1 NOT NULL,
    error text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    unit_key text NOT NULL,
    generation integer DEFAULT 1 NOT NULL,
    CONSTRAINT provenance_batch_apr_hash_check CHECK ((apr_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT provenance_batch_batch_key_check CHECK ((batch_key ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT provenance_batch_code_key_check CHECK ((code_key ~ '^[0-9a-f]{32,64}$'::text)),
    CONSTRAINT provenance_batch_completed_check CHECK (((status <> 'completed'::text) OR ((row_count IS NOT NULL) AND (finished_at IS NOT NULL)))),
    CONSTRAINT provenance_batch_generation_check CHECK ((generation >= 1)),
    CONSTRAINT provenance_batch_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{32,64}$'::text)),
    CONSTRAINT provenance_batch_range_check CHECK ((range_start < range_end)),
    CONSTRAINT provenance_batch_status_check CHECK ((status = ANY (ARRAY['started'::text, 'completed'::text, 'failed'::text, 'superseded'::text]))),
    CONSTRAINT provenance_batch_symbols_check CHECK ((cardinality(symbols) > 0)),
    CONSTRAINT provenance_batch_symbols_hash_check CHECK ((symbols_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT provenance_batch_unit_key_check CHECK ((unit_key ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE public.provenance_batch OWNER TO postgres;

--
-- Name: TABLE provenance_batch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.provenance_batch IS 'Bulk-load lineage and idempotency record (phase 186, migration 386, D-24/D-37): one row per bulk_load unit, primary key batch_key is the idempotency key, so a rerun with the same identity is a no-op and a killed or failed run is retried on the same key. Append-only: identity columns are immutable, completed rows are frozen, rows are never deleted. Sole writer: services/_batch_utils.py bulk_load.';


--
-- Name: COLUMN provenance_batch.unit_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.provenance_batch.unit_key IS 'sha256 of (writer, target_table, tf, replace_where) (migration 416): the identity of the unit whose rows a replacing load owns. Every completed row sharing it, other than the current batch_key, is flipped to superseded by the replace path.';


--
-- Name: COLUMN provenance_batch.generation; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.provenance_batch.generation IS '1 for the first row of a batch_key (migration 418); a superseded identity that returns loads as a new row with generation + 1. Immutable. batch_key stays the content identity.';


