    duration_ms integer,
    error_message text,
    changed_by text NOT NULL,
    reason text
);


ALTER TABLE public.remediation_ledger OWNER TO postgres;

--
-- Name: remediation_success_rates; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.remediation_success_rates AS
 SELECT action,
    count(*) AS attempt_count,
    sum(
        CASE
            WHEN (outcome = 'success'::text) THEN 1
            ELSE 0
        END) AS success_count,
    ((sum(
        CASE
            WHEN (outcome = 'success'::text) THEN 1
            ELSE 0
        END))::double precision / (NULLIF(count(*), 0))::double precision) AS success_rate
   FROM public.remediation_ledger
  WHERE ("timestamp" > (now() - '30 days'::interval))
  GROUP BY action
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.remediation_success_rates OWNER TO postgres;

--
-- Name: research_run_series; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.research_run_series (
    run_id uuid NOT NULL,
    sessions date[] NOT NULL,
    d_s double precision[] NOT NULL,
    written_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT research_run_series_lengths_check CHECK (((cardinality(sessions) > 0) AND (cardinality(sessions) = cardinality(d_s))))
);


ALTER TABLE public.research_run_series OWNER TO postgres;

--
-- Name: TABLE research_run_series; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.research_run_series IS 'Per-session E17 D_s of each counted attempt, the StepM selection universe (design 7.3.2, migration 515). Insert-only, for a run already terminal as completed or failed. Sole writer: src/intelligence/research/ledger.py.';


--
-- Name: roll_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.roll_events (
    id bigint NOT NULL,
    detected_at timestamp with time zone NOT NULL,
    base_symbol text NOT NULL,
    old_contract text NOT NULL,
    new_contract text NOT NULL,
    detection_method text NOT NULL,
    volume_zscore double precision,
    confirmation_count integer,
    scheduled_roll_date date,
    is_authoritative boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT roll_events_detection_method_check CHECK ((detection_method = ANY (ARRAY['volume'::text, 'calendar'::text])))
);


ALTER TABLE public.roll_events OWNER TO postgres;

--
-- Name: TABLE roll_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.roll_events IS 'All roll detection events (volume + calendar) for ML training and operational audit.';


--
-- Name: COLUMN roll_events.scheduled_roll_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.roll_events.scheduled_roll_date IS 'Calendar-scheduled roll_end date (expiry-3 days) from contracts.py get_roll_window().';


--
-- Name: COLUMN roll_events.is_authoritative; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.roll_events.is_authoritative IS 'True for the first event that triggered the operational front-month promotion.';


--
-- Name: roll_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.roll_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.roll_events_id_seq OWNER TO postgres;

--
-- Name: roll_events_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.roll_events_id_seq OWNED BY public.roll_events.id;


--
-- Name: service_health_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.service_health_events (
    ts timestamp with time zone NOT NULL,
    service text NOT NULL,
    event_type text NOT NULL,
    previous_state text,
    reason text,
    lag_messages bigint,
    restart_count integer,
    duration_degraded_s double precision,
    id bigint NOT NULL
);


ALTER TABLE public.service_health_events OWNER TO postgres;

--
-- Name: service_health_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.service_health_events ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.service_health_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: shadow_registry; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.shadow_registry (
    component_name text NOT NULL,
    component_type text NOT NULL,
    is_shadow boolean DEFAULT true NOT NULL,
    enrolled_at timestamp with time zone DEFAULT now() NOT NULL,
    promoted_at timestamp with time zone,
    demoted_at timestamp with time zone,
    min_n integer DEFAULT 100 NOT NULL,
    min_ev_r double precision DEFAULT 0.0 NOT NULL,
    ci_alpha double precision DEFAULT 0.05 NOT NULL,
    demotion_lookback_days integer DEFAULT 30 NOT NULL,
    demotion_threshold_ev_r double precision DEFAULT '-0.05'::numeric NOT NULL,
    demotion_min_evaluations integer DEFAULT 3 NOT NULL,
    demotion_consecutive_count integer DEFAULT 0 NOT NULL,
    last_eval_n integer,
    last_eval_ev_r double precision,
    last_eval_ci_lower double precision,
    last_eval_win_rate double precision,
    last_eval_at timestamp with time zone,
    CONSTRAINT shadow_registry_component_type_check CHECK ((component_type = ANY (ARRAY['i7_plugin'::text, 'swarm_agent'::text])))
);


ALTER TABLE public.shadow_registry OWNER TO postgres;

--
-- Name: TABLE shadow_registry; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.shadow_registry IS 'Per-component shadow state and gate parameters. Single source of truth.';


--
-- Name: COLUMN shadow_registry.is_shadow; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.shadow_registry.is_shadow IS 'TRUE = shadow mode (not live); FALSE = live (promoted). Default TRUE.';


--
-- Name: COLUMN shadow_registry.demotion_consecutive_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.shadow_registry.demotion_consecutive_count IS 'Rolling count of consecutive eval periods where EV[R] < demotion_threshold_ev_r.';


--
-- Name: system_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.system_events (
    id bigint NOT NULL,
    event_type character varying(50) NOT NULL,
    base_symbol character varying(10) NOT NULL,
    old_symbol character varying(10),
    new_symbol character varying(10),
    roll_gap double precision,
    roll_direction character varying(10),
    detected_at timestamp with time zone DEFAULT now(),
    event_data jsonb DEFAULT '{}'::jsonb
);


ALTER TABLE public.system_events OWNER TO postgres;

--
-- Name: TABLE system_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.system_events IS 'Durable audit log for system-level events: roll detection, pipeline resets';


--
-- Name: COLUMN system_events.event_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.event_type IS 'Event class (e.g. ''roll'', ''pipeline_reset'', ''subscription_change'')';


--
-- Name: COLUMN system_events.base_symbol; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.base_symbol IS 'Base futures symbol (e.g. ''ES'') — always present';


--
-- Name: COLUMN system_events.old_symbol; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.old_symbol IS 'Previous contract symbol at roll (e.g. ''ESM6'')';


--
-- Name: COLUMN system_events.new_symbol; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.new_symbol IS 'New front-month symbol after roll (e.g. ''ESU6'')';


--
-- Name: COLUMN system_events.roll_gap; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.roll_gap IS 'Absolute price gap at roll boundary (close_old vs open_new)';


--
-- Name: COLUMN system_events.roll_direction; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.roll_direction IS 'Roll price direction: up / down / flat / unknown';


--
-- Name: COLUMN system_events.event_data; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.system_events.event_data IS 'Arbitrary JSON payload for extensibility (z_score, confirmation_bars, etc.)';


--
-- Name: system_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.system_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.system_events_id_seq OWNER TO postgres;

