--
-- Name: tag_vocabulary; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tag_vocabulary (
    tag text NOT NULL,
    category text NOT NULL,
    description text NOT NULL,
    factor_series text,
    measurement_type text DEFAULT 'beta_regression'::text NOT NULL,
    lookback_days integer DEFAULT 252 NOT NULL,
    loading_threshold double precision,
    half_life_days integer DEFAULT 180 NOT NULL,
    CONSTRAINT tag_vocabulary_category_check CHECK ((category = ANY (ARRAY['exposure'::text, 'sensitivity'::text, 'factor_regime'::text, 'cycle_position'::text, 'signal_role'::text, 'macro_driver'::text]))),
    CONSTRAINT tag_vocabulary_measurement_type_check CHECK ((measurement_type = ANY (ARRAY['beta_regression'::text, 'correlation'::text, 'cross_correlation'::text, 'mutual_information'::text, 'definitional'::text])))
);


ALTER TABLE public.tag_vocabulary OWNER TO postgres;

--
-- Name: vocabulary_group; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vocabulary_group (
    namespace text NOT NULL,
    group_name text NOT NULL,
    label text NOT NULL,
    description text,
    sort_order integer DEFAULT 0 NOT NULL
);


ALTER TABLE public.vocabulary_group OWNER TO postgres;

--
-- Name: TABLE vocabulary_group; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.vocabulary_group IS 'Named grouping within a controlled_vocabulary namespace (e.g. regime_hmm/trending, regime_cross_sectional_equity/low_vol). Groups are independent and may overlap - a code can belong to more than one group in the same namespace (e.g. regime_hmm/trending_up belongs to both trending and bullish_bias). This is why the shape is a join table (vocabulary_group_member) rather than a single parent_code column on controlled_vocabulary.';


--
-- Name: vocabulary_group_member; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vocabulary_group_member (
    namespace text NOT NULL,
    group_name text NOT NULL,
    code text NOT NULL
);


ALTER TABLE public.vocabulary_group_member OWNER TO postgres;

--
-- Name: TABLE vocabulary_group_member; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.vocabulary_group_member IS 'Join table: which controlled_vocabulary codes belong to which vocabulary_group, within the same namespace. Composite FKs to both parent tables enforce referential integrity - a membership row can never reference a code or group that does not exist.';


